import sys

def main():
    data = sys.stdin.read().split()
    if not data:
        return
    n = int(data[0])
    s = data[1]

    count = 0
    for i, char in enumerate(s):
        digit = int(char)
        if digit % 2 == 0:
            count += (i + 1)

    print(count)

if __name__ == "__main__":
    main()
